package edu.casestudy.merkle.web;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.userdetails.*;import org.springframework.security.provisioning.InMemoryUserDetailsManager;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@Configuration public class SecurityConfig {@Bean SecurityFilterChain chain(HttpSecurity h,@Value("${app.security-enabled}")boolean enabled)throws Exception{h.csrf(c->c.disable());if(!enabled)h.authorizeHttpRequests(a->a.anyRequest().permitAll());else h.authorizeHttpRequests(a->a.requestMatchers("/actuator/health").permitAll().anyRequest().hasRole("ADMIN")).httpBasic(x->{});return h.build();}@Bean UserDetailsService users(@Value("${app.admin-password}")String pass){String p=pass.isBlank()?java.util.UUID.randomUUID().toString():pass;return new InMemoryUserDetailsManager(User.withUsername("admin").password(new BCryptPasswordEncoder().encode(p)).roles("ADMIN").build());}}
